import React, { useRef, useState, useEffect } from 'react'
import { View, Text, Animated, Dimensions, TouchableOpacity, Button } from 'react-native'

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';


export function Alert() {
    const { selectedNumber, setSelectedNumber, alertActive, setAlertActive, shoppingCartItem } = useContexState();
    const tempShoppingCartItem = [...shoppingCartItem];
    const index = tempShoppingCartItem.indexOf(Number(selectedNumber));

    const fadeAnim = useRef(new Animated.Value(0)).current;
    const [active, setActive] = useState(false);
    const [alertMessage, setAlertMessage] = useState('');

    function fade(value: number, message = '') {
        setActive(true)
        Animated.timing(fadeAnim, {
            toValue: value,
            duration: 1000,
        } as Animated.TimingAnimationConfig).start(() => {
            if (value === 0) {
                setActive(false);
                setAlertMessage(message);
            };
        });
    };


    function AlertStart(message: string) {
        fade(1, message);
        console.log(123123123);
    }


    function AlertTSX() {
        return <>
            <Button onPress={() => AlertStart('O número já está no carrinho!')} title='Button' />
            {active ? <>
                <TouchableOpacity
                    onPress={() => { fade(0) }}
                    style={{
                        position: 'absolute',
                        alignItems: 'center',
                        justifyContent: 'center',
                        minWidth: Dimensions.get('window').width,
                        minHeight: Dimensions.get('window').height
                    }} />

                <Animated.View style={[styles.container, { opacity: fadeAnim }]} >
                    <Text style={styles.listText}>{alertMessage}</Text>
                </Animated.View>
            </> : null}
        </>
    }


    //transform: [{ scale: fadeAnim }]
    return { AlertTSX, AlertStart }
};










